+            recipientPrivateKey.algorithm.name,
+            recipientPrivateKey,
+            capsuleBytes,
+            'HKDF',
+            false,
+            ['deriveKey'],
+          );
+          return crypto.subtle.deriveKey(
+            {
+              name: 'HKDF',
+              hash: 'SHA-256',
+              salt: new Uint8Array(32),
+              info: infoBytes,
+            },
+            hkdfBaseKey,
+            { name: 'AES-GCM', length: 256 },
+            false,
+            ['encrypt', 'decrypt'],
+          );
