+        copyEnvelopeBtn: document.getElementById('copy-envelope-btn'),
+        decryptVerifyBtn: document.getElementById('decrypt-verify-btn'),
+        tamperTestBtn: document.getElementById('tamper-test-btn'),
+        restoreEnvelopeBtn: document.getElementById('restore-envelope-btn'),
+        decryptionResultContainer: document.getElementById('decryption-result-container'),
+        decryptionStatus: document.getElementById('decryption-status'),
+        decryptedNoteText: document.getElementById('decrypted-note-text'),
+        decryptedMetadataText: document.getElementById('decrypted-metadata-text'),
+        savedNotesCount: document.getElementById('saved-notes-count'),
+        savedNotesList: document.getElementById('saved-notes-list')
+      };
+
+      function updateAadPreview() {
+        const keyId = state.recipientKeys ? state.recipientKeys.keyId : 'DG-K-INIT';
+        els.aadPreview.value = buildAadString({
+          orderId: els.orderIdInput.value,
+          accessType: els.accessTypeSelect.value,
+          mode: state.mode,
+          keyId,
+          ttl: els.noteTtlSelect.value
+        });
+      }
+
+      function renderSessionTelemetry(session) {
+        if (!session || !state.recipientKeys) return;
+        const rk = state.recipientKeys;
+
+        const badgeLabels = {
+          'hybrid': 'Hybrid PQ + Classical • ML-KEM-768 + ECDH P-256 • AES-256-GCM',
+          'pq-mlkem768': 'Post-Quantum KEM • ML-KEM-768 (FIPS 203) • AES-256-GCM',
+          'classical-ecdh': 'Classical Key Agreement • ECDH P-256 • AES-256-GCM'
+        };
+        els.activeBadge.textContent = badgeLabels[session.mode] || badgeLabels['hybrid'];
+
+        els.recipientKeyId.textContent = `${rk.keyId} (${session.suite})`;
+        els.classicalPubKey.textContent =
+          session.mode === 'pq-mlkem768'
+            ? `Standby (${abbrevHex(rk.ecdhPubRaw, 8, 4)})`
+            : `ECDH P-256: ${abbrevHex(rk.ecdhPubRaw, 8, 4)}`;
+        els.pqPubKey.textContent =
+          session.mode === 'classical-ecdh'
+            ? `Standby (${abbrevHex(rk.mlKemKeyPair.publicKey, 8, 4)})`
+            : `ML-KEM-768 ek: ${abbrevHex(rk.mlKemKeyPair.publicKey, 8, 4)}`;
+
+        if (session.mode === 'hybrid') {
+          els.kemCiphertext.textContent =
+            `ML-KEM ct: ${abbrevHex(session.mlKemCiphertext, 6, 4)} | Ephem ECDH: ${abbrevHex(session.ephemeralEcdhPubRaw, 6, 4)}`;
+          els.componentSecrets.textContent =
+            `ss_ecdh: ${session.classicalSharedSecretHex.slice(0, 16)}… (32 B) + ss_pq: ${session.pqSharedSecretHex.slice(0, 16)}… (32 B)`;
+        } else if (session.mode === 'pq-mlkem768') {
+          els.kemCiphertext.textContent =
+            `ML-KEM-768 ct: ${abbrevHex(session.mlKemCiphertext, 8, 6)}`;
+          els.componentSecrets.textContent =
+            `ss_pq (ML-KEM-768): ${session.pqSharedSecretHex.slice(0, 24)}… (32 B / 256-bit)`;
+        } else {
+          els.kemCiphertext.textContent =
+            `Ephemeral ECDH P-256 Pub: ${abbrevHex(session.ephemeralEcdhPubRaw, 8, 6)}`;
+          els.componentSecrets.textContent =
+            `ss_ecdh (P-256 DH): ${session.classicalSharedSecretHex.slice(0, 24)}… (32 B / 256-bit)`;
+        }
+
+        els.combinedSecret.textContent =
+          `HKDF-SHA-256 -> AES-256-GCM: ${session.combinedSharedSecretHex.slice(0, 24)}… (Key FP: ${session.derivedKeyFingerprintHex.slice(0, 16)})`;
+
+        els.handshakeStatus.className = 'status-banner success';
+        els.handshakeStatus.textContent =
+          `Shared Secret Established (${session.suite}) — 256-bit AES-GCM Key Derived via HKDF-SHA-256`;
+      }
+
+      function renderEnvelopeOutput(envelope, isTampered = false) {
+        if (!envelope) return;
+
+        els.envelopeSuite.textContent = `${envelope.suite} (AEAD: ${envelope.aeadCipher}, KDF: ${envelope.kdf})`;
+
+        const kemParts = [];
+        if (envelope.mlKemCiphertextHex) {
+          const ctLen = envelope.mlKemCiphertextHex.length / 2;
+          kemParts.push(`ML-KEM-768 ct (${ctLen} B): ${envelope.mlKemCiphertextBase64.slice(0, 28)}…`);
+        }
+        if (envelope.ephemeralEcdhPublicKeyHex) {
+          const ephemLen = envelope.ephemeralEcdhPublicKeyHex.length / 2;
+          kemParts.push(`Ephem ECDH P-256 (${ephemLen} B): ${envelope.ephemeralEcdhPublicKeyBase64.slice(0, 28)}…`);
+        }
+        els.encapsulatedKeyOutput.textContent = kemParts.join(' | ') || '—';
+
+        els.ivOutput.textContent = `${envelope.ivHex} (Base64: ${envelope.ivBase64})`;
+        els.authTagOutput.textContent = `${envelope.authTagHex} (Base64: ${envelope.authTagBase64})`;
+        els.ciphertextOutput.textContent = `${envelope.ciphertextBase64} (Hex: ${envelope.ciphertextHex.slice(0, 48)}${envelope.ciphertextHex.length > 48 ? '…' : ''})`;
+        els.aadOutput.textContent = envelope.aad;
+        els.envelopeJsonOutput.textContent = JSON.stringify(envelope, null, 2);
+
+        if (isTampered) {
+          els.encryptionStatus.className = 'status-banner error';
+          els.encryptionStatus.textContent =
+            'WARNING: Active Envelope Ciphertext / Tag Has Been Modified (Tampered State)';
+        } else {
+          els.encryptionStatus.className = 'status-banner success';
+          els.encryptionStatus.textContent =
+            `Encrypted & Sealed in Browser (${envelope.aeadCipher} • 128-bit Auth Tag • ${envelope.mode.toUpperCase()} Key Encapsulation)`;
+        }
+      }
+
+      async function verifyCurrentEnvelope() {
+        if (!state.currentEnvelope) return;
+        try {
+          const res = await decryptDeliveryNote(state.currentEnvelope, state.recipientKeys);
+          els.decryptionResultContainer.classList.remove('tampered');
+          els.decryptionStatus.style.color = '#1b5e20';
+          els.decryptionStatus.textContent =
+            `Authenticated & Decrypted Successfully — 128-bit AES-GCM Tag & AAD Verified (${res.suite})`;
+          els.decryptedNoteText.textContent = res.plaintext;
+          els.decryptedMetadataText.textContent =
+            `Order: ${res.metadata.orderId || state.currentEnvelope.orderId} | Type: ${res.metadata.accessType || state.currentEnvelope.accessType} | Key ID: ${state.currentEnvelope.recipientKeyId} | Shared Secret: ${res.sharedSecretHex.slice(0, 16)}…`;
+          return res;
+        } catch (err) {
+          els.decryptionResultContainer.classList.add('tampered');
+          els.decryptionStatus.style.color = '#b71c1c';
+          els.decryptionStatus.textContent =
+            'AEAD Authentication Failed! Tampering detected in ciphertext, 128-bit GCM authentication tag, or AAD — decryption rejected.';
+          els.decryptedNoteText.textContent = '[DECRYPTION BLOCKED — UNAUTHENTICATED OR CORRUPTED PAYLOAD]';
+          els.decryptedMetadataText.textContent = 'Integrity check failed (WebCrypto AES-GCM OperationError)';
+          return { verified: false, error: err };
+        }
+      }
+
+      function renderSavedQueue() {
+        els.savedNotesCount.textContent = `${state.savedEnvelopes.length} Encrypted Note${state.savedEnvelopes.length === 1 ? '' : 's'}`;
+        els.savedNotesList.innerHTML = '';
+
+        state.savedEnvelopes.forEach((env, idx) => {
+          const card = document.createElement('div');
+          card.className = 'saved-note-card';
+          card.setAttribute('data-envelope-id', env.id);
+
+          const modeBadgeMap = {
+            'hybrid': 'Hybrid PQ + Classical',
+            'pq-mlkem768': 'Post-Quantum ML-KEM-768',
+            'classical-ecdh': 'Classical ECDH P-256'
+          };
+
+          card.innerHTML = `
+            <div>
+              <div class="saved-note-meta">
+                <span>Order: <strong>${env.orderId}</strong> (${env.accessType})</span>
+                <span class="badge-mode">${modeBadgeMap[env.mode] || env.mode}</span>
+              </div>
+              <div style="margin-top: 8px; font-family: monospace; font-size: 0.77rem; color: #3e2723; word-break: break-all;">
+                <div><strong>AEAD Ciphertext:</strong> ${env.ciphertextBase64.slice(0, 36)}…</div>
+                <div><strong>GCM Tag:</strong> ${env.authTagHex.slice(0, 20)}… | <strong>IV:</strong> ${env.ivHex}</div>
+              </div>
+            </div>
+            <div style="display: flex; gap: 8px;">
+              <button type="button" class="btn inspect-note-btn" data-index="${idx}" style="margin-top: 0; padding: 6px 12px; font-size: 0.78rem;">
+                Inspect &amp; Decrypt
+              </button>
+              <button type="button" class="btn btn-outline delete-note-btn" data-index="${idx}" style="margin-top: 0; padding: 6px 12px; font-size: 0.78rem;">
+                Remove
+              </button>
+            </div>
+          `;
+          els.savedNotesList.appendChild(card);
+        });
+
+        els.savedNotesList.querySelectorAll('.inspect-note-btn').forEach((btn) => {
+          btn.addEventListener('click', async () => {
+            const idx = Number(btn.getAttribute('data-index'));
+            const env = state.savedEnvelopes[idx];
+            if (env) {
+              state.currentEnvelope = JSON.parse(JSON.stringify(env));
+              state.originalEnvelopeBackup = JSON.parse(JSON.stringify(env));
+              els.restoreEnvelopeBtn.hidden = true;
+              renderEnvelopeOutput(state.currentEnvelope, false);
+              await verifyCurrentEnvelope();
+            }
+          });
+        });
+
+        els.savedNotesList.querySelectorAll('.delete-note-btn').forEach((btn) => {
+          btn.addEventListener('click', () => {
+            const idx = Number(btn.getAttribute('data-index'));
+            state.savedEnvelopes.splice(idx, 1);
+            renderSavedQueue();
+          });
+        });
+      }
+
+      async function setProtectionMode(newMode) {
+        if (!SUITE_NAMES[newMode]) return;
+        state.mode = newMode;
+        els.modeSelect.value = newMode;
+        els.modePills.forEach((pill) => {
+          pill.classList.toggle('active', pill.getAttribute('data-mode') === newMode);
+        });
+        updateAadPreview();
+        const session = await establishSharedSecret(newMode, state.recipientKeys);
+        state.activeSession = session;
+        renderSessionTelemetry(session);
+      }
+
+      // =========================================================================
+      // Event Listeners
+      // =========================================================================
+      els.modeSelect.addEventListener('change', (e) => {
+        setProtectionMode(e.target.value);
+      });
+
+      els.modePills.forEach((pill) => {
+        pill.addEventListener('click', () => {
+          setProtectionMode(pill.getAttribute('data-mode'));
+        });
+      });
+
+      els.establishBtn.addEventListener('click', async () => {
+        const session = await establishSharedSecret(state.mode, state.recipientKeys);
+        state.activeSession = session;
+        renderSessionTelemetry(session);
+      });
+
+      els.rotateKeysBtn.addEventListener('click', async () => {
+        state.recipientKeys = await generateRecipientKeys();
+        const session = await establishSharedSecret(state.mode, state.recipientKeys);
+        state.activeSession = session;
+        updateAadPreview();
+        renderSessionTelemetry(session);
+      });
+
+      [els.orderIdInput, els.accessTypeSelect, els.noteTtlSelect].forEach((input) => {
+        input.addEventListener('input', updateAadPreview);
+        input.addEventListener('change', updateAadPreview);
+      });
+
+      els.presetChips.forEach((chip) => {
+        chip.addEventListener('click', () => {
+          els.accessCodeInput.value = chip.getAttribute('data-pin') || '';
+          els.accessTypeSelect.value = chip.getAttribute('data-type') || 'gate-code';
+          els.noteInput.value = chip.getAttribute('data-note') || '';
+          updateAadPreview();
+        });
+      });
+
+      els.clearFormBtn.addEventListener('click', () => {
+        els.accessCodeInput.value = '';
+        els.noteInput.value = '';
+      });
+
+      els.form.addEventListener('submit', async (e) => {
+        e.preventDefault();
+        const rawNote = els.noteInput.value.trim();
+        const rawPin = els.accessCodeInput.value.trim();
+        const noteToEncrypt = rawNote || (rawPin ? `Use access code ${rawPin} at entry.` : 'Leave coffee order at front door.');
+
+        const { envelope, session } = await encryptDeliveryNote({
+          note: noteToEncrypt,
+          orderId: els.orderIdInput.value,
+          accessType: els.accessTypeSelect.value,
+          accessCode: rawPin,
+          mode: state.mode,
+          ttl: els.noteTtlSelect.value
+        });
+
+        state.currentEnvelope = JSON.parse(JSON.stringify(envelope));
+        state.originalEnvelopeBackup = JSON.parse(JSON.stringify(envelope));
+        state.savedEnvelopes.unshift(envelope);
+        els.restoreEnvelopeBtn.hidden = true;
+
+        renderSessionTelemetry(session);
+        renderEnvelopeOutput(state.currentEnvelope, false);
+        await verifyCurrentEnvelope();
+        renderSavedQueue();
+      });
+
+      els.decryptVerifyBtn.addEventListener('click', async () => {
+        await verifyCurrentEnvelope();
+      });
+
+      els.tamperTestBtn.addEventListener('click', async () => {
+        if (!state.currentEnvelope) return;
+        const ctBytes = base64ToBytes(state.currentEnvelope.ciphertextBase64);
+        if (ctBytes.length > 0) {
+          ctBytes[0] ^= 0xff; // Flip bits in ciphertext
+        }
+        state.currentEnvelope.ciphertextBase64 = bytesToBase64(ctBytes);
+        state.currentEnvelope.ciphertextHex = bytesToHex(ctBytes);
+        els.restoreEnvelopeBtn.hidden = false;
+
+        renderEnvelopeOutput(state.currentEnvelope, true);
+        await verifyCurrentEnvelope();
+      });
+
+      els.restoreEnvelopeBtn.addEventListener('click', async () => {
+        if (!state.originalEnvelopeBackup) return;
+        state.currentEnvelope = JSON.parse(JSON.stringify(state.originalEnvelopeBackup));
+        els.restoreEnvelopeBtn.hidden = true;
+        renderEnvelopeOutput(state.currentEnvelope, false);
+        await verifyCurrentEnvelope();
+      });
+
+      els.copyEnvelopeBtn.addEventListener('click', async () => {
+        if (!state.currentEnvelope) return;
+        const jsonStr = JSON.stringify(state.currentEnvelope, null, 2);
+        try {
+          if (navigator.clipboard && navigator.clipboard.writeText) {
+            await navigator.clipboard.writeText(jsonStr);
+          }
+          els.copyEnvelopeBtn.textContent = 'Copied Encrypted JSON!';
+          setTimeout(() => {
+            els.copyEnvelopeBtn.textContent = 'Copy Encrypted Envelope JSON';
+          }, 1800);
+        } catch (_) {}
+      });
+
+      // =========================================================================
+      // Expose Programmatic API on window.DailyGrindCrypto
+      // =========================================================================
+      const readyPromise = (async function initializeCryptoFeature() {
+        state.recipientKeys = await generateRecipientKeys();
+        const session = await establishSharedSecret('hybrid', state.recipientKeys);
+        state.activeSession = session;
+        updateAadPreview();
+        renderSessionTelemetry(session);
+
+        // Encrypt an initial demonstration envelope so the inspector & verifier are immediately active
+        const initialDemo = await encryptDeliveryNote({
+          note: 'Gate code #4821*, take elevator to 4th floor, leave Maple Oat Latte on mat by Apt 4B.',
+          orderId: 'DG-2026-8492',
+          accessType: 'gate-code',
+          accessCode: '#4821*',
+          mode: 'hybrid',
+          ttl: 'burn-after-delivery'
+        });
+        state.currentEnvelope = JSON.parse(JSON.stringify(initialDemo.envelope));
+        state.originalEnvelopeBackup = JSON.parse(JSON.stringify(initialDemo.envelope));
+        state.savedEnvelopes.push(initialDemo.envelope);
+
+        renderEnvelopeOutput(state.currentEnvelope, false);
+        await verifyCurrentEnvelope();
+        renderSavedQueue();
+        return state;
+      })();
+
+      window.DailyGrindCrypto = {
+        ready: readyPromise,
+        getState: () => state,
+        mlKem768: {
+          keygen: mlKemKeygen,
+          encapsulate: mlKemEncapsulate,
+          decapsulate: mlKemDecapsulate
+        },
+        generateRecipientKeys,
+        establishSharedSecret,
+        decapsulateSharedSecret,
+        encryptDeliveryNote,
+        decryptDeliveryNote,
+        setProtectionMode
+      };
+    })();
+  </script>
 </body>

