new file mode 100644
index 0000000..410d7ed
--- /dev/null
+++ b/styles.css
@@ -0,0 +1,298 @@
+/* Critical Styles & Cross-Document View Transitions for The Daily Grind */
+@view-transition {
+  navigation: auto;
+}
+
+:root {
+  --primary: #4e342e;
+  --secondary: #d7ccc8;
+  --accent: #ffab40;
+  --text: #3e2723;
+  --light: #fafafa;
+  --card-bg: #ffffff;
+  --hero-height: 60vh;
+}
+
+:root[data-theme="dark"] {
+  --primary: #3e2723;
+  --secondary: #2d1e1b;
+  --accent: #ffab40;
+  --text: #f5ebe6;
+  --light: #1a1210;
+  --card-bg: #261a17;
+}
+
+* {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+html {
+  scroll-behavior: smooth;
+}
+
+body {
+  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+  line-height: 1.6;
+  color: var(--text);
+  background-color: var(--light);
+  min-height: 100vh;
+  display: flex;
+  flex-direction: column;
+}
+
+/* Navigation */
+nav {
+  background: var(--primary);
+  color: white;
+  padding: 1rem 5%;
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  position: sticky;
+  top: 0;
+  z-index: 1000;
+  min-height: 64px;
+  contain: layout style;
+  view-transition-name: site-nav;
+}
+
+.logo {
+  font-size: 1.5rem;
+  font-weight: bold;
+  letter-spacing: 1px;
+  view-transition-name: brand-logo;
+}
+
+.logo a {
+  color: white;
+  text-decoration: none;
+}
+
+nav ul {
+  display: flex;
+  list-style: none;
+  align-items: center;
+}
+
+nav ul li {
+  margin-left: 20px;
+}
+
+nav a {
+  color: white;
+  text-decoration: none;
+  font-size: 0.9rem;
+  transition: color 0.3s;
+}
+
+nav a:hover,
+nav a[aria-current="page"] {
+  color: var(--accent);
+}
+
+.logout-link {
+  border: 1px solid var(--accent);
+  padding: 5px 12px;
+  border-radius: 4px;
+}
+
+/* Hero Section - Fixed/reserved dimensions for layout stability before transition */
+.hero {
+  height: var(--hero-height);
+  min-height: 360px;
+  background-color: #3e2723;
+  background-image: linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)),
+    url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80');
+  background-size: cover;
+  background-position: center;
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  align-items: center;
+  color: white;
+  text-align: center;
+  padding: 0 20px;
+  contain: layout paint;
+  view-transition-name: hero-banner;
+}
+
+.hero h1 {
+  font-size: 3rem;
+  margin-bottom: 1rem;
+  view-transition-name: hero-title;
+}
+
+.hero p {
+  font-size: 1.15rem;
+  max-width: 640px;
+  view-transition-name: hero-subtitle;
+}
+
+.hero .btn {
+  view-transition-name: hero-cta;
+}
+
+/* Content Sections */
+.container {
+  max-width: 1100px;
+  width: 100%;
+  margin: 40px auto;
+  padding: 0 20px;
+  flex: 1 0 auto;
+}
+
+#seasonal-favorites {
+  min-height: 260px;
+  contain: layout style;
+  view-transition-name: seasonal-favorites-section;
+}
+
+#seasonal-favorites h2,
+.section-title {
+  text-align: center;
+  margin-bottom: 10px;
+  view-transition-name: section-heading;
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
+  gap: 20px;
+  margin-top: 20px;
+}
+
+.card {
+  background: var(--card-bg);
+  padding: 20px;
+  border-radius: 8px;
+  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+  text-align: center;
+  min-height: 180px;
+  display: flex;
+  flex-direction: column;
+  justify-content: space-between;
+  align-items: center;
+  contain: layout style;
+}
+
+.card-img {
+  width: 100%;
+  height: 180px;
+  aspect-ratio: 16 / 10;
+  object-fit: cover;
+  border-radius: 6px;
+  margin-bottom: 12px;
+  background-color: var(--secondary);
+}
+
+#card-maple-oat {
+  view-transition-name: card-maple-oat;
+}
+
+#card-dark-roast {
+  view-transition-name: card-dark-roast;
+}
+
+#card-cold-brew {
+  view-transition-name: card-cold-brew;
+}
+
+.card h3 {
+  margin-bottom: 10px;
+  color: var(--primary);
+}
+
+:root[data-theme="dark"] .card h3 {
+  color: var(--accent);
+}
+
+.btn {
+  display: inline-block;
+  background: var(--primary);
+  color: white;
+  padding: 10px 20px;
+  text-decoration: none;
+  border-radius: 5px;
+  margin-top: 15px;
+  transition: background 0.3s, transform 0.2s;
+}
+
+.btn:hover {
+  background: #3e2723;
+}
+
+/* Footer - Not render-blocking */
+footer {
+  background: var(--secondary);
+  text-align: center;
+  padding: 40px 20px;
+  margin-top: 40px;
+  content-visibility: auto;
+  contain-intrinsic-size: auto 140px;
+}
+
+.footer-links {
+  margin-bottom: 20px;
+}
+
+.footer-links a {
+  margin: 0 10px;
+  color: var(--text);
+  text-decoration: none;
+  font-size: 0.85rem;
+}
+
+/* View Transition Animations */
+@keyframes vt-fade-in {
+  from {
+    opacity: 0;
+    transform: translateY(12px);
+  }
+  to {
+    opacity: 1;
+    transform: translateY(0);
+  }
+}
+
+@keyframes vt-fade-out {
+  from {
+    opacity: 1;
+    transform: translateY(0);
+  }
+  to {
+    opacity: 0;
+    transform: translateY(-12px);
+  }
+}
+
+::view-transition-old(root) {
+  animation: 220ms cubic-bezier(0.4, 0, 1, 1) both vt-fade-out;
+}
+
+::view-transition-new(root) {
+  animation: 280ms cubic-bezier(0, 0, 0.2, 1) 40ms both vt-fade-in;
+}
+
+::view-transition-group(site-nav),
+::view-transition-group(brand-logo),
+::view-transition-group(hero-banner),
+::view-transition-group(hero-title),
+::view-transition-group(hero-subtitle),
+::view-transition-group(hero-cta),
+::view-transition-group(seasonal-favorites-section),
+::view-transition-group(card-maple-oat),
+::view-transition-group(card-dark-roast),
+::view-transition-group(card-cold-brew) {
+  animation-duration: 300ms;
+  animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
+}
+
+@media (prefers-reduced-motion: reduce) {
+  ::view-transition-group(*),
+  ::view-transition-old(*),
+  ::view-transition-new(*) {
+    animation-duration: 0.01ms !important;
+  }
+}
