+  double p = f.x>f.y && f.x>f.z ? f.x : f.y>f.z ? f.y : f.z; // max refl
+  if (++depth>5) {
+    if (depth>50 || smallpt_erand48(Xi)>=p) return obj.e; // R.R. with hard cap for stack safety
+    f=f*(1/p);
+  }
+  if (obj.refl == DIFF){                  // Ideal DIFFUSE reflection
