+
+extern "C" {
+
+void set_sphere_color(int index, double r, double g, double b) {
+  int count = static_cast<int>(sizeof(spheres) / sizeof(Sphere));
+  if (index >= 0 && index < count) {
+    spheres[index].c = Vec(r, g, b);
+  }
+}
+
+void reset_default_colors() {
+  spheres[0].c = Vec(.75, .25, .25);      // Left
+  spheres[1].c = Vec(.25, .25, .75);      // Rght
+  spheres[2].c = Vec(.75, .75, .75);      // Back
+  spheres[3].c = Vec();                   // Frnt
+  spheres[4].c = Vec(.75, .75, .75);      // Botm
+  spheres[5].c = Vec(.75, .75, .75);      // Top
+  spheres[6].c = Vec(1, 1, 1) * .999;     // Mirr
+  spheres[7].c = Vec(1, 1, 1) * .999;     // Glas
+  spheres[8].c = Vec();                   // Lite
+}
+
+void randomize_sphere_colors(unsigned int seed) {
+  unsigned short Xi[3] = {
+    static_cast<unsigned short>(seed & 0xFFFFU),
+    static_cast<unsigned short>((seed >> 16) & 0xFFFFU),
+    static_cast<unsigned short>((seed ^ 0xA5A5U) & 0xFFFFU)
+  };
