+  const int indices[] = {0, 1, 2, 4, 5, 6, 7};
+  for (int idx : indices) {
+    double r = 0.15 + 0.80 * smallpt_erand48(Xi);
+    double g = 0.15 + 0.80 * smallpt_erand48(Xi);
+    double b = 0.15 + 0.80 * smallpt_erand48(Xi);
+    spheres[idx].c = Vec(r, g, b);
+  }
+}
+
+void render_frame(uint8_t *out_rgba, int w, int h, int samples_per_subpixel) {
+  int samps = samples_per_subpixel > 0 ? samples_per_subpixel : 1;
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+  Vec cx=Vec(w*.5135/h), cy=(cx%cam.d).norm()*.5135, r;
+  Vec *c = static_cast<Vec*>(std::calloc(w * h, sizeof(Vec)));
+  if (!c) return;
+
+  for (int y=0; y<h; y++){                       // Loop over image rows
+    for (unsigned short x=0, Xi[3]={0,0,static_cast<unsigned short>(y*y*y)}; x<w; x++) // Loop cols
+      for (int sy=0, i=(h-y-1)*w+x; sy<2; sy++)     // 2x2 subpixel rows
+        for (int sx=0; sx<2; sx++, r=Vec()){        // 2x2 subpixel cols
+          for (int s=0; s<samps; s++){
+            double r1=2*smallpt_erand48(Xi), dx=r1<1 ? std::sqrt(r1)-1: 1-std::sqrt(2-r1);
+            double r2=2*smallpt_erand48(Xi), dy=r2<1 ? std::sqrt(r2)-1: 1-std::sqrt(2-r2);
+            Vec d = cx*( ( (sx+.5 + dx)/2 + x)/w - .5) +
+                    cy*( ( (sy+.5 + dy)/2 + y)/h - .5) + cam.d;
+            r = r + radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*(1./samps);
+          } // Camera rays are pushed ^^^^^ forward to start in interior
+          c[i] = c[i] + Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+        }
+  }
+
+  for (int i=0; i<w*h; i++) {
+    out_rgba[i * 4 + 0] = static_cast<uint8_t>(toInt(c[i].x));
+    out_rgba[i * 4 + 1] = static_cast<uint8_t>(toInt(c[i].y));
+    out_rgba[i * 4 + 2] = static_cast<uint8_t>(toInt(c[i].z));
+    out_rgba[i * 4 + 3] = 255;
+  }
+
+  std::free(c);
+}
+
+}
