+    setDirection('prev');
+    setCurrentIndex((prev) => (prev - 1 + stories.length) % stories.length);
+    setStep((prev) => prev + 1);
+  };
+
+  const handleNext = () => {
+    setDirection('next');
+    setCurrentIndex((prev) => (prev + 1) % stories.length);
+    setStep((prev) => prev + 1);
+  };
+
+  const currentStory = stories[currentIndex];
+  const formattedDate =
+    currentStory.data.date instanceof Date
+      ? currentStory.data.date.toLocaleDateString()
+      : new Date(currentStory.data.date).toLocaleDateString();
+
+  const animationClass =
+    direction === 'next'
+      ? 'slide-from-right'
+      : direction === 'prev'
+      ? 'slide-from-left'
+      : '';
+
+  return (
+    <section aria-label="Top Stories" className="bg-white border-b border-gray-300">
+      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
+        <div className="flex items-center justify-between gap-4">
+          <button
+            type="button"
+            onClick={handlePrevious}
+            aria-label="Previous"
+            className="flex items-center gap-1 px-3 py-1.5 text-sm font-medium text-gray-700 bg-gray-100 hover:bg-gray-200 rounded transition-colors cursor-pointer shrink-0"
+          >
+            <ChevronLeftIcon className="w-4 h-4" aria-hidden="true" />
+            <span>Previous</span>
+          </button>
+
+          <div className="overflow-hidden flex-1">
+            <div
+              key={step}
+              data-direction={direction ?? undefined}
+              className={`text-center ${animationClass}`}
+            >
+              <a href={`${import.meta.env.BASE_URL}articles/${currentStory.id}`}>
+                <h3 className="font-bold text-gray-900 hover:text-amber-400 cursor-pointer">
+                  {currentStory.data.title}
+                </h3>
+              </a>
+              <span className="text-xs text-gray-500">{formattedDate}</span>
+            </div>
+          </div>
+
+          <button
+            type="button"
+            onClick={handleNext}
+            aria-label="Next"
+            className="flex items-center gap-1 px-3 py-1.5 text-sm font-medium text-gray-700 bg-gray-100 hover:bg-gray-200 rounded transition-colors cursor-pointer shrink-0"
+          >
+            <span>Next</span>
+            <ChevronRightIcon className="w-4 h-4" aria-hidden="true" />
+          </button>
+        </div>
+      </div>
+    </section>
+  );
+}
