+      </span>
+      <span>PulseFlow</span>
+    </a>
+    <nav aria-label="Primary Navigation">
+      <ul class="nav-links">
+        <li><a href="#features">Features</a></li>
+        <li><a href="#metrics">Benchmarks</a></li>
+        <li><a href="#cta-button">Get Started</a></li>
+      </ul>
+    </nav>
+  </header>
+
+  <main>
+    <section
+      id="hero"
+      class="hero"
+      data-experiment="hero-section"
+      aria-labelledby="hero-title"
+    >
+      <div class="hero-content" id="hero-variant-container" data-experiment-cloak>
+        <div class="hero-badge" data-experiment-target="badge">
+          <span class="hero-badge-dot" aria-hidden="true"></span>
+          <span>PulseFlow 3.0 Release</span>
+        </div>
+
+        <h1 id="hero-title" class="hero-title" data-experiment-target="headline">
+          Turn Product Telemetry into Instant Revenue Growth
+        </h1>
+
+        <p id="hero-subtitle" class="hero-subtitle" data-experiment-target="subheadline">
+          Deploy zero-latency feature experiments, monitor conversion funnels in real time, and ship confident product decisions across your entire stack.
+        </p>
+
+        <div class="hero-actions">
+          <button
+            id="cta-button"
+            class="cta-button"
+            type="button"
+            data-experiment-target="cta"
+          >
+            <span>Start Free 14-Day Trial</span>
+            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
+              <line x1="5" y1="12" x2="19" y2="12"></line>
+              <polyline points="12 5 19 12 12 19"></polyline>
+            </svg>
+          </button>
+          <a href="#features" class="secondary-link">Explore Architecture</a>
+        </div>
+
+        <p id="cta-feedback" class="cta-feedback" role="status" aria-live="polite"></p>
+
+        <div class="hero-meta">
+          <span>&#10003; No credit card required</span>
+          <span>&#10003; Sub-millisecond edge evaluation</span>
+        </div>
+      </div>
+
+      <div class="hero-visual" id="metrics" aria-label="Live Experiment Telemetry Preview">
+        <div class="visual-header">
+          <div class="window-dots" aria-hidden="true">
+            <span class="window-dot"></span>
+            <span class="window-dot"></span>
+            <span class="window-dot"></span>
+          </div>
+          <span class="visual-status">Edge SDK Active</span>
+        </div>
+
+        <div class="metrics-grid">
+          <div class="metric-card">
+            <div class="metric-label">Conversion Lift</div>
+            <div class="metric-value">+28.4%</div>
+            <div class="metric-delta">99.2% statistical confidence</div>
+          </div>
+          <div class="metric-card">
+            <div class="metric-label">P99 Evaluation</div>
+            <div class="metric-value">0.4 ms</div>
+            <div class="metric-delta">Zero layout shift</div>
+          </div>
+        </div>
+
+        <svg width="100%" height="130" viewBox="0 0 420 130" fill="none" role="img" aria-label="Conversion rate comparison chart">
+          <defs>
+            <linearGradient id="chartGrad" x1="0" y1="0" x2="0" y2="1">
+              <stop offset="0%" stop-color="#6366f1" stop-opacity="0.45" />
+              <stop offset="100%" stop-color="#6366f1" stop-opacity="0.0" />
+            </linearGradient>
+          </defs>
+          <path d="M10 105 C70 95, 110 80, 160 68 C210 56, 260 52, 310 30 C350 15, 385 12, 410 8 L410 120 L10 120 Z" fill="url(#chartGrad)" />
+          <path d="M10 105 C70 95, 110 80, 160 68 C210 56, 260 52, 310 30 C350 15, 385 12, 410 8" stroke="#818cf8" stroke-width="3" stroke-linecap="round" />
+          <path d="M10 112 C75 108, 130 102, 190 96 C250 90, 320 86, 410 78" stroke="#64748b" stroke-width="2" stroke-dasharray="5 5" stroke-linecap="round" />
+        </svg>
+      </div>
+    </section>
+
+    <section id="features" class="features-section" aria-label="Platform Capabilities">
+      <article class="feature-card">
+        <h2>Flicker-Free Experimentation</h2>
+        <p>Scoped opacity cloaking and layout containment ensure users never experience a flash of unstyled or original variant content.</p>
+      </article>
+      <article class="feature-card">
+        <h2>Resilient Fail-Safe Delivery</h2>
+        <p>Non-blocking script execution paired with strict timeout guards keeps First Contentful Paint and Largest Contentful Paint fast.</p>
+      </article>
+      <article class="feature-card">
+        <h2>Instant Funnel Attribution</h2>
+        <p>Correlate every CTA interaction with downstream retention and revenue metrics in real time without third-party bloat.</p>
+      </article>
+    </section>
+  </main>
+
+  <footer class="site-footer">
+    <p>&copy; 2026 PulseFlow Inc. Built for high-velocity product teams.</p>
+  </footer>
+
+  <script>
+    (function () {
+      var heroContainer = document.getElementById('hero-variant-container');
+      if (heroContainer && typeof MutationObserver !== 'undefined') {
+        var observer = new MutationObserver(function () {
+          if (window.__revealExperiment) {
+            window.__revealExperiment();
+          }
+          observer.disconnect();
+        });
+        observer.observe(heroContainer, {
+          childList: true,
+          subtree: true,
+          characterData: true
+        });
+      }
+
+      var ctaButton = document.getElementById('cta-button');
+      var ctaFeedback = document.getElementById('cta-feedback');
+      if (ctaButton && ctaFeedback) {
+        ctaButton.addEventListener('click', function () {
+          ctaFeedback.textContent = 'Your 14-day trial workspace is ready — check your invite link.';
+        });
+      }
+    })();
+  </script>
+</body>
+</html>

