+  <script>
+    (function () {
+      const searchInput = document.getElementById('search-input');
+      const cards = document.querySelectorAll('.grid .card');
+
+      function clearHighlights(root) {
+        const marks = root.querySelectorAll('mark.highlight');
+        marks.forEach((mark) => {
+          const parent = mark.parentNode;
+          while (mark.firstChild) {
+            parent.insertBefore(mark.firstChild, mark);
+          }
+          parent.removeChild(mark);
+        });
+        root.normalize();
+      }
+
+      function escapeRegExp(str) {
+        return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
+      }
+
+      function highlightTextNodes(root, regex) {
+        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
+        const textNodes = [];
+        let currentNode = walker.nextNode();
+        while (currentNode) {
+          if (currentNode.nodeValue && currentNode.nodeValue.trim().length > 0) {
+            textNodes.push(currentNode);
+          }
+          currentNode = walker.nextNode();
+        }
+
+        textNodes.forEach((textNode) => {
+          const text = textNode.nodeValue;
+          regex.lastIndex = 0;
+          if (!regex.test(text)) {
+            return;
+          }
+          regex.lastIndex = 0;
+
+          const fragment = document.createDocumentFragment();
+          let lastIndex = 0;
+          let match;
+
+          while ((match = regex.exec(text)) !== null) {
+            if (match.index > lastIndex) {
+              fragment.appendChild(document.createTextNode(text.slice(lastIndex, match.index)));
+            }
+            const mark = document.createElement('mark');
+            mark.className = 'highlight';
+            mark.style.backgroundColor = 'gold';
+            mark.appendChild(document.createTextNode(match[0]));
+            fragment.appendChild(mark);
+            lastIndex = regex.lastIndex;
+            if (match[0].length === 0) {
+              regex.lastIndex++;
+            }
+          }
+
+          if (lastIndex < text.length) {
+            fragment.appendChild(document.createTextNode(text.slice(lastIndex)));
+          }
+
+          textNode.parentNode.replaceChild(fragment, textNode);
+        });
+      }
+
+      function handleSearch() {
+        const query = searchInput.value;
+        cards.forEach((card) => {
+          clearHighlights(card);
+        });
+
+        if (!query || query.trim().length === 0) {
+          return;
+        }
+
+        const regex = new RegExp(escapeRegExp(query), 'gi');
+        cards.forEach((card) => {
+          highlightTextNodes(card, regex);
+        });
+      }
+
+      if (searchInput) {
+        searchInput.addEventListener('input', handleSearch);
+        searchInput.addEventListener('keyup', handleSearch);
+      }
+    })();
