+        ctaText: 'Order Cold Brew',
+        ctaHref: '/order-online',
+      },
+    };
+
+    const dynamicViewRoot = document.getElementById('dynamic-view-root');
+
+    function renderRouteView(pathname, source = 'navigation', label = pathname) {
+      perfTelemetry.lastInteractionContext = {
+        source,
+        label,
+        route: pathname,
+        timestamp: performance.now(),
+      };
+
+      if (pathname === '/' || !VIEWS[pathname]) {
+        dynamicViewRoot.replaceChildren();
+        return;
+      }
+
+      const view = VIEWS[pathname];
+      const panel = document.createElement('article');
+      panel.className = 'view-panel';
+      panel.id = `view-${pathname.replace(/[^a-z0-9]+/gi, '-')}`;
+
+      panel.innerHTML = `
+        <div class="view-panel-header">
+          <div>
+            <span class="badge">${view.badge}</span>
+            <h2>${view.title}</h2>
+          </div>
+          <a href="/" class="btn" data-interaction-source="${source}">Back to Home</a>
+        </div>
+        <div class="view-panel-body">
+          <div>
+            <p style="font-size: 1.05rem; margin-bottom: 12px;">${view.description}</p>
+            <p style="font-weight: bold; color: var(--primary); font-size: 1.1rem;">${view.price}</p>
+            <a href="${view.ctaHref}" class="btn" data-interaction-source="${source}">${view.ctaText}</a>
+          </div>
+          <div>
+            <img
+              src="${view.image}"
+              alt="${view.imageAlt}"
+              width="640"
+              height="400"
+            >
+          </div>
+        </div>
+      `;
+
+      dynamicViewRoot.replaceChildren(panel);
+    }
+
+    function navigateTo(pathname, source, label) {
+      renderRouteView(pathname, source, label);
+      if (window.location.pathname !== pathname) {
+        history.pushState({ pathname, source }, '', pathname);
+      }
+    }
+
+    // Handle interactions on navigation bar, "Order Now" button, and "Seasonal Favorites" cards
+    document.addEventListener('click', (event) => {
+      const target = event.target instanceof Element ? event.target : null;
+      if (!target) return;
+
+      const logoEl = target.closest('.logo[data-nav-target]');
+      if (logoEl) {
+        event.preventDefault();
+        navigateTo('/', 'navbar', 'THE DAILY GRIND');
+        return;
+      }
+
+      const linkEl = target.closest('a[href]');
+      if (linkEl) {
+        const href = linkEl.getAttribute('href');
+        if (href && href.startsWith('/') && (href === '/' || VIEWS[href])) {
+          event.preventDefault();
+          const source =
+            linkEl.getAttribute('data-interaction-source') ||
+            (linkEl.closest('nav') ? 'navbar' : 'page');
+          const label = linkEl.textContent?.trim() || href;
+          navigateTo(href, source, label);
+          return;
+        }
+      }
+
+      const cardEl = target.closest('.card[data-route]');
+      if (cardEl) {
+        const route = cardEl.getAttribute('data-route');
+        if (route && VIEWS[route]) {
+          event.preventDefault();
+          const title = cardEl.querySelector('h3')?.textContent?.trim() || route;
+          navigateTo(route, 'seasonal-favorites', title);
+        }
+      }
+    });
+
+    window.addEventListener('popstate', () => {
+      renderRouteView(window.location.pathname, 'history-popstate', window.location.pathname);
+    });
+  </script>
+
 </body>

