+        if (countBadge) {
+          countBadge.textContent = column.querySelectorAll('.card').length;
+        }
+      });
+    }
+
+    function updateCardActions(card, status) {
+      const actions = card.querySelector('.order-actions');
+      if (!actions) return;
+      if (status === 'queued') {
+        actions.innerHTML = '<button type="button" data-move-to="brewing">Start Brewing →</button>';
+      } else if (status === 'brewing') {
+        actions.innerHTML = '<button type="button" data-move-to="queued">← Queue</button><button type="button" data-move-to="ready">Mark Ready →</button>';
+      } else if (status === 'ready') {
+        actions.innerHTML = '<button type="button" data-move-to="brewing">← Brewing</button>';
+      }
+    }
+
+    function moveItemToColumn(itemId, columnId) {
+      const item = document.getElementById(itemId);
+      const column = document.getElementById(columnId);
+      if (!item || !column) return;
+
+      // With content-visibility: auto (and contain fallback), the browser
+      // isolates layout recalculation to the affected columns rather than reflowing the page.
+      column.appendChild(item);
+      updateCardActions(item, column.dataset.status || column.id);
+      updateColumnCounts();
+    }
+
+    document.addEventListener('dragstart', (event) => {
+      const card = event.target.closest('.board-column .card');
+      if (!card) return;
+      draggedCardId = card.id;
+      card.classList.add('dragging');
+      if (event.dataTransfer) {
+        event.dataTransfer.effectAllowed = 'move';
+        event.dataTransfer.setData('text/plain', card.id);
+      }
+    });
+
+    document.addEventListener('dragend', (event) => {
+      const card = event.target.closest('.board-column .card');
+      if (card) {
+        card.classList.remove('dragging');
+      }
+      columns.forEach((col) => col.classList.remove('drag-over'));
+      draggedCardId = null;
+    });
+
+    columns.forEach((column) => {
+      column.addEventListener('dragover', (event) => {
+        event.preventDefault();
+        if (event.dataTransfer) {
+          event.dataTransfer.dropEffect = 'move';
+        }
+        if (!column.classList.contains('drag-over')) {
+          column.classList.add('drag-over');
+        }
+      });
+
+      column.addEventListener('dragleave', (event) => {
+        if (!column.contains(event.relatedTarget)) {
+          column.classList.remove('drag-over');
+        }
+      });
+
+      column.addEventListener('drop', (event) => {
+        event.preventDefault();
+        column.classList.remove('drag-over');
+        const id = (event.dataTransfer && event.dataTransfer.getData('text/plain')) || draggedCardId;
+        if (id) {
+          moveItemToColumn(id, column.id);
+        }
+      });
+    });
