+          v_uv = a_uv;
+          v_color = a_color;
+        }
+      `;
+
+      const fsSource = `#version 300 es
+        precision highp float;
+
+        in vec2 v_uv;
+        in vec3 v_color;
+
+        uniform sampler2D u_texture;
+        uniform bool u_useTexture;
+
+        out vec4 outColor;
+
+        void main() {
