+      const uMvpLoc = gl.getUniformLocation(program, "u_mvp");
+      const uUseTextureLoc = gl.getUniformLocation(program, "u_useTexture");
+      const uTextureLoc = gl.getUniformLocation(program, "u_texture");
+
+      // 1. Unit quad (-0.5 to 0.5) for the front interactive HTML form face
+      const frontQuadVertices = new Float32Array([
+        // x,    y,   z,   u, v,   r, g, b
+        -0.5, -0.5, 0.0,   0, 1,   1, 1, 1,
+         0.5, -0.5, 0.0,   1, 1,   1, 1, 1,
+         0.5,  0.5, 0.0,   1, 0,   1, 1, 1,
+        -0.5, -0.5, 0.0,   0, 1,   1, 1, 1,
+         0.5,  0.5, 0.0,   1, 0,   1, 1, 1,
+        -0.5,  0.5, 0.0,   0, 0,   1, 1, 1,
+      ]);
