+      const frontVao = gl.createVertexArray();
+      gl.bindVertexArray(frontVao);
+      const frontVbo = gl.createBuffer();
+      gl.bindBuffer(gl.ARRAY_BUFFER, frontVbo);
+      gl.bufferData(gl.ARRAY_BUFFER, frontQuadVertices, gl.STATIC_DRAW);
