+        -hw,  hh, -hd,  1, 0,  0.24, 0.15, 0.12,
+         hw,  hh, -hd,  0, 0,  0.24, 0.15, 0.12,
+
+        // Left face (warm roasted chestnut)
+        -hw, -hh, -hd,  0, 1,  0.36, 0.23, 0.18,
+        -hw, -hh,  hd,  1, 1,  0.36, 0.23, 0.18,
+        -hw,  hh,  hd,  1, 0,  0.36, 0.23, 0.18,
+        -hw, -hh, -hd,  0, 1,  0.36, 0.23, 0.18,
+        -hw,  hh,  hd,  1, 0,  0.36, 0.23, 0.18,
+        -hw,  hh, -hd,  0, 0,  0.36, 0.23, 0.18,
+
+        // Right face (warm roasted chestnut)
+         hw, -hh,  hd,  0, 1,  0.33, 0.20, 0.16,
+         hw, -hh, -hd,  1, 1,  0.33, 0.20, 0.16,
+         hw,  hh, -hd,  1, 0,  0.33, 0.20, 0.16,
+         hw, -hh,  hd,  0, 1,  0.33, 0.20, 0.16,
