+    }
+
+    setBusyKeyId(pk.id);
+    setFeedback(null);
+
+    try {
+      const response = await fetch(`${import.meta.env.BASE_URL}api/passkeys.json`, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
