+            const publicKeyOptions = {
+              challenge,
+              rp: {
+                name: 'The Daily Grind Coffee Co.',
+                id: rpId
+              },
+              user: {
+                id: userIdBytes,
+                name: customer.email,
+                displayName: customer.fullName
