+      // WebAuthn Credential Assertion Ceremony (Sign-In & Step-Up Reauthentication)
+      async function assertPasskeyCredential(targetCustomer, specificPasskeyId) {
+        const challenge = randomBytes(32);
+        const rpId = window.location.hostname || 'localhost';
