+        const nativeCandidates = candidatePasskeys.filter(pk => pk.mode === 'webauthn');
+        if (!useVirtualAuthenticator && nativeWebAuthnSupported && nativeCandidates.length > 0) {
+          try {
+            const allowCredentials = nativeCandidates.map(pk => ({
+              id: base64UrlToBuffer(pk.credentialId),
+              type: 'public-key'
+            }));
