@@ -0,0 +1,86 @@
+// Privacy by Design & Security Headers configuration for The Daily Grind
+// Applies defensive HTTP headers, Connection-Allowlist, Fetch Metadata isolation,
+// secure cookie helpers (__Host- and CHIPS Partitioned), and Clear-Site-Data on /logout.
+
+export const SECURITY_HEADERS = {
+  'Referrer-Policy': 'strict-origin-when-cross-origin',
+  'Permissions-Policy':
+    'geolocation=(), camera=(), microphone=(), accelerometer=(), focus-without-user-activation=()',
+  'X-Content-Type-Options': 'nosniff',
+  'X-Frame-Options': 'DENY',
+  'Strict-Transport-Security': 'max-age=31536000; includeSubDomains; preload',
+  'Cross-Origin-Opener-Policy': 'same-origin-allow-popups',
+  'Cross-Origin-Resource-Policy': 'same-origin',
+  'Reporting-Endpoints': 'main-endpoint="https://reports.dailygrind.example/main"',
+  'Connection-Allowlist':
+    '(response-origin "https://images.unsplash.com/*" "https://www.youtube-nocookie.com/*" "https://x.com/intent/*" "https://bsky.app/intent/*"); report-to=main-endpoint'
+};
+
+export function buildContentSecurityPolicy(nonce) {
+  const scriptSource = nonce ? `'nonce-${nonce}' 'strict-dynamic'` : `'self'`;
+  return [
+    "default-src 'self'",
+    `script-src ${scriptSource} 'report-sample'`,
+    "style-src 'self' 'unsafe-inline'",
+    "img-src 'self' https://images.unsplash.com https://img.youtube.com data:",
+    'frame-src https://www.youtube-nocookie.com',
+    "connect-src 'self'",
+    "form-action 'self'",
+    "worker-src 'self'",
+    "object-src 'none'",
+    "base-uri 'none'",
+    "frame-ancestors 'none'",
+    "require-trusted-types-for 'script'",
+    'report-to main-endpoint'
+  ].join('; ');
+}
+
+export function createSecureSessionCookie(sessionId) {
+  return `__Host-session_id=${encodeURIComponent(sessionId)}; SameSite=Lax; HttpOnly; Secure; Path=/`;
+}
+
+export function createPartitionedEmbedCookie(name, value) {
+  return `${encodeURIComponent(name)}=${encodeURIComponent(value)}; SameSite=None; Secure; Path=/; Partitioned; HttpOnly`;
+}
+
+export function applyPrivacyAndSecurityHeaders(req, res, next) {
+  const setHeader = (name, value) =>
+    typeof res.setHeader === 'function' ? res.setHeader(name, value) : res.headers?.set(name, value);
+
+  // Vary on Fetch Metadata headers to prevent cache poisoning
+  setHeader('Vary', 'Sec-Fetch-Dest, Sec-Fetch-Mode, Sec-Fetch-Site');
+
+  // Enforce Fetch Metadata resource isolation before route processing
+  const site = typeof req.get === 'function' ? req.get('Sec-Fetch-Site') : req.headers?.['sec-fetch-site'];
+  const mode = typeof req.get === 'function' ? req.get('Sec-Fetch-Mode') : req.headers?.['sec-fetch-mode'];
+  const dest = typeof req.get === 'function' ? req.get('Sec-Fetch-Dest') : req.headers?.['sec-fetch-dest'];
+
+  if (site && !['same-origin', 'same-site', 'none'].includes(site)) {
+    const isSafeNavigation =
+      site === 'cross-site' &&
+      mode === 'navigate' &&
+      req.method === 'GET' &&
+      !['object', 'embed'].includes(dest);
+    if (!isSafeNavigation) {
+      if (typeof res.status === 'function') {
+        return res.status(403).send('Forbidden');
+      }
+      res.statusCode = 403;
+      return res.end('Forbidden');
+    }
+  }
+
+  for (const [headerName, headerValue] of Object.entries(SECURITY_HEADERS)) {
+    setHeader(headerName, headerValue);
+  }
+  setHeader('Content-Security-Policy', buildContentSecurityPolicy(res.locals?.nonce));
+
+  // Clear-Site-Data on logout route to ensure no lingering data remains in the browser
+  if (req.url === '/logout' || req.path === '/logout') {
+    setHeader('Clear-Site-Data', '"cookies", "storage", "cache"');
+  }
+
+  if (typeof next === 'function') {
+    next();
+  }
+}

