+
+function isValidEmail(email) {
+  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && email.length <= 254;
+}
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.mjs': 'application/javascript; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.ico': 'image/x-icon',
+};
+
+const server = http.createServer(async (req, res) => {
+  const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+  const pathname = url.pathname;
+
+  // Reporting endpoint for Connection-Allowlist and CSP violation reports
+  if (req.method === 'POST' && pathname === '/api/security-reports') {
+    try {
+      await readRequestBody(req);
+      res.writeHead(204);
+      res.end();
+    } catch {
+      res.writeHead(400);
+      res.end();
+    }
+    return;
+  }
+
+  // Newsletter signup endpoint
+  if (
+    req.method === 'POST' &&
+    (pathname === '/api/newsletter' || pathname === '/newsletter' || pathname === '/subscribe')
+  ) {
+    setSecurityHeaders(req, res);
+    try {
+      const rawBody = await readRequestBody(req);
+      const email = parseEmailFromBody(rawBody, req.headers['content-type'] || '');
+
+      if (!isValidEmail(email)) {
+        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(
+          JSON.stringify({
+            ok: false,
+            message: 'Please enter a valid email address (for example, alex@example.com).',
+          }),
+        );
+        return;
+      }
+
+      SUBSCRIBERS.add(email.toLowerCase());
+      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(
+        JSON.stringify({
+          ok: true,
+          email,
+          message: `Thanks for subscribing! We'll send roasting notes and seasonal drops to ${email}.`,
+        }),
+      );
+    } catch {
+      res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(
+        JSON.stringify({
+          ok: false,
+          message: 'We could not process your signup request. Please try again.',
+        }),
+      );
+    }
+    return;
+  }
+
+  // Serve homepage and static files
+  if (req.method === 'GET' || req.method === 'HEAD') {
+    const relativePath = pathname === '/' ? 'index.html' : pathname.replace(/^\/+/, '');
+    const resolvedPath = path.resolve(__dirname, relativePath);
+
+    if (!resolvedPath.startsWith(__dirname)) {
+      res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('Forbidden');
+      return;
+    }
+
+    try {
+      const ext = path.extname(resolvedPath).toLowerCase();
+      const contentType = MIME_TYPES[ext] || 'application/octet-stream';
+
+      if (ext === '.html') {
+        const nonce = crypto.randomBytes(16).toString('base64');
+        setSecurityHeaders(req, res, { nonce });
+        let html = await fs.readFile(resolvedPath, 'utf8');
+        html = html.replaceAll('__CSP_NONCE__', nonce);
+        res.writeHead(200, { 'Content-Type': contentType });
+        res.end(req.method === 'HEAD' ? undefined : html);
+        return;
+      }
+
+      setSecurityHeaders(req, res);
+      const content = await fs.readFile(resolvedPath);
+      res.writeHead(200, { 'Content-Type': contentType });
+      res.end(req.method === 'HEAD' ? undefined : content);
+    } catch {
+      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('Not Found');
+    }
+    return;
+  }
+
+  res.writeHead(405, { 'Content-Type': 'text/plain; charset=utf-8' });
+  res.end('Method Not Allowed');
+});
+
+if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+  server.listen(PORT, () => {
+    console.log(`Daily Grind server listening on http://localhost:${PORT}`);
+  });
+}
+
+export { server };

