+  <script>
+    (function () {
+      const nav = document.querySelector('nav');
+      const navLinks = Array.from(document.querySelectorAll('nav a[href^="#"]'));
+      const sections = navLinks
+        .map((link) => {
+          const id = link.getAttribute('href').slice(1);
+          return document.getElementById(id);
+        })
+        .filter(Boolean);
+
+      function setActiveLink(activeId) {
+        navLinks.forEach((link) => {
+          const isMatch = link.getAttribute('href') === '#' + activeId;
+          link.classList.toggle('active', isMatch);
+          if (isMatch) {
+            link.setAttribute('aria-current', 'true');
+          } else {
+            link.removeAttribute('aria-current');
+          }
+        });
+      }
+
+      function updateActiveSection() {
+        if (!sections.length) return;
+
+        const navHeight = nav ? nav.offsetHeight : 0;
+        const viewportHeight = window.innerHeight || document.documentElement.clientHeight;
+        const scrollBottom = window.scrollY + viewportHeight;
+        const docHeight = document.documentElement.scrollHeight;
+
+        // If scrolled to the bottom of the document, highlight the last visible section
+        if (docHeight - scrollBottom <= 15) {
+          for (let i = sections.length - 1; i >= 0; i--) {
+            const rect = sections[i].getBoundingClientRect();
+            if (rect.bottom > navHeight && rect.top < viewportHeight) {
+              setActiveLink(sections[i].id);
+              return;
+            }
+          }
+        }
+
+        // Focal point 35% into the viewport below the sticky navigation bar
+        const focalPoint = navHeight + (viewportHeight - navHeight) * 0.35;
+
+        let activeSectionId = null;
+        let maxVisibleHeight = 0;
+        let bestVisibleId = null;
+
+        for (const section of sections) {
+          const rect = section.getBoundingClientRect();
+          const visibleTop = Math.max(rect.top, navHeight);
+          const visibleBottom = Math.min(rect.bottom, viewportHeight);
+          const visibleHeight = Math.max(0, visibleBottom - visibleTop);
+
+          if (visibleHeight > maxVisibleHeight) {
+            maxVisibleHeight = visibleHeight;
+            bestVisibleId = section.id;
+          }
+
+          if (rect.top <= focalPoint && rect.bottom >= focalPoint) {
+            activeSectionId = section.id;
+          }
+        }
+
+        if (activeSectionId) {
+          setActiveLink(activeSectionId);
+        } else if (bestVisibleId) {
+          setActiveLink(bestVisibleId);
+        }
+      }
+
+      navLinks.forEach((link) => {
+        link.addEventListener('click', () => {
+          const targetId = link.getAttribute('href').slice(1);
+          setActiveLink(targetId);
+        });
+      });
+
+      if ('IntersectionObserver' in window) {
+        const observer = new IntersectionObserver(
+          () => {
+            updateActiveSection();
+          },
+          {
+            root: null,
+            rootMargin: '-10% 0px -10% 0px',
+            threshold: [0, 0.1, 0.25, 0.5, 0.75, 1]
+          }
+        );
+        sections.forEach((section) => observer.observe(section));
+      }
+
+      window.addEventListener('scroll', updateActiveSection, { passive: true });
+      window.addEventListener('resize', updateActiveSection, { passive: true });
+      window.addEventListener('hashchange', updateActiveSection);
+      document.addEventListener('DOMContentLoaded', updateActiveSection);
+      updateActiveSection();
+    })();
+  </script>
