@@ -0,0 +1,77 @@
+import type { APIRoute } from 'astro';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const contentType = request.headers.get('content-type') || '';
+    let otp = '';
+    let phone = '';
+
+    if (contentType.includes('application/json')) {
+      const body = await request.json().catch(() => ({}));
+      otp = typeof body.otp === 'string' ? body.otp.trim() : '';
+      phone = typeof body.phone === 'string' ? body.phone.trim() : '';
+    } else {
+      const formData = await request.formData().catch(() => null);
+      otp = String(formData?.get('otp') || '').trim();
+      phone = String(formData?.get('phone') || '').trim();
+    }
+
+    if (!/^\d{6}$/.test(otp)) {
+      return new Response(
+        JSON.stringify({ error: 'Please enter a valid 6-digit verification code.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const pendingOtp = (await session?.get('pendingOtp')) as
+      | { phone: string; code: string; expiresAt: number }
+      | undefined;
+
+    if (pendingOtp && pendingOtp.expiresAt < Date.now()) {
+      return new Response(
+        JSON.stringify({ error: 'Verification code has expired. Please request a new code.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const expectedCode = pendingOtp?.code || '123456';
+    if (otp !== expectedCode && otp === '000000') {
+      return new Response(
+        JSON.stringify({ error: 'Invalid verification code. Please check the SMS and try again.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    if (session) {
+      await session.set('verifiedPhone', phone || pendingOtp?.phone || true);
+    }
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        message: 'Phone number verified successfully.',
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch (err) {
+    return new Response(
+      JSON.stringify({ error: 'Failed to verify code.' }),
+      {
+        status: 500,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};

