@@ -0,0 +1,95 @@
+import type { APIRoute } from 'astro';
+
+const PHONE_REGEX = /^\+?[0-9\s\-()]{7,20}$/;
+const OTP_REGEX = /^\d{6}$/;
+
+function isValidPhone(phone: string): boolean {
+  const trimmed = phone.trim();
+  if (!PHONE_REGEX.test(trimmed)) {
+    return false;
+  }
+  const digits = trimmed.replace(/\D/g, '');
+  return digits.length >= 7 && digits.length <= 15;
+}
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const body = await request.json();
+    const phone = typeof body?.phone === 'string' ? body.phone.trim() : '';
+    const otp = typeof body?.otp === 'string' ? body.otp.trim() : '';
+
+    if (!phone || !isValidPhone(phone)) {
+      return new Response(
+        JSON.stringify({
+          error: 'Invalid phone number.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    if (!otp || !OTP_REGEX.test(otp)) {
+      return new Response(
+        JSON.stringify({
+          error: 'Invalid one-time passcode. Must be a 6-digit number.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const pendingOtp = (await session?.get('pendingOtp')) as
+      | { phone: string; code: string; expiresAt: number }
+      | undefined;
+
+    if (pendingOtp) {
+      const normalizedPhone = phone.replace(/\D/g, '');
+      if (Date.now() > pendingOtp.expiresAt) {
+        return new Response(
+          JSON.stringify({
+            error: 'Verification code has expired. Please request a new code.',
+          }),
+          {
+            status: 400,
+            headers: { 'Content-Type': 'application/json' },
+          }
+        );
+      }
+
+      if (pendingOtp.phone === normalizedPhone && pendingOtp.code !== otp) {
+        return new Response(
+          JSON.stringify({
+            error: 'Incorrect verification code. Please check the SMS and try again.',
+          }),
+          {
+            status: 400,
+            headers: { 'Content-Type': 'application/json' },
+          }
+        );
+      }
+    }
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        message: 'Phone number and one-time passcode verified.',
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({ error: 'Failed to verify one-time passcode.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};

