+        return {
+          ...event,
+          sequenceNumber: sortedIndex + 1,
+          intervalNanoseconds: deltaNanoseconds,
+          intervalDuration: duration,
+          intervalFormatted: formatNanosecondInterval(deltaNanoseconds),
+          intervalIso: duration.toString(),
+          isSubMillisecondInterval: deltaNanoseconds > 0n && deltaNanoseconds < 1000000n
+        };
+      });
+    }
