+      const intervals = processed.slice(1).map((e) => e.intervalNanoseconds);
+      const minIntervalNs = intervals.reduce((min, val) => (val < min ? val : min), intervals[0] || 0n);
+      const maxIntervalNs = intervals.reduce((max, val) => (val > max ? val : max), intervals[0] || 0n);
+      const firstInstant = processed[0].instant;
+      const lastInstant = processed[processed.length - 1].instant;
+      const totalSpanNs = lastInstant.epochNanoseconds - firstInstant.epochNanoseconds;
