+      document.getElementById('stat-total-events').textContent = `${processed.length} events`;
+      document.getElementById('stat-total-span').textContent = formatNanosecondInterval(totalSpanNs).replace(/^\+/, '');
+      document.getElementById('stat-min-interval').textContent = formatNanosecondInterval(minIntervalNs);
+      document.getElementById('stat-max-interval').textContent = formatNanosecondInterval(maxIntervalNs);
+      summaryEl.hidden = false;
+
+      const rowsHtml = processed
+        .map((evt) => {
