+                <div class="mono" style="font-size:0.75rem;color:#795548;">${evt.epochNanoseconds.toString()} ns</div>
+              </td>
+              <td>
+                <span class="${intervalBadgeClass}">${evt.intervalFormatted}</span>
+                <div class="mono" style="font-size:0.75rem;color:#795548;">ISO: ${evt.intervalIso}</div>
+              </td>
+            </tr>
+          `;
+        })
+        .join('');
+
+      containerEl.innerHTML = `
+        <div class="events-table-wrapper">
+          <table class="events-table" id="sorted-events-table">
+            <thead>
+              <tr>
+                <th>Order</th>
+                <th>Backend Service</th>
+                <th>Order Event</th>
+                <th>UTC Timestamp (Nanosecond Precision)</th>
+                <th>Interval Since Previous Event</th>
+              </tr>
+            </thead>
+            <tbody>
+              ${rowsHtml}
+            </tbody>
+          </table>
+        </div>
+      `;
+
+      return processed;
+    }
+
+    document.getElementById('load-events-btn').addEventListener('click', () => {
+      renderProcessedEvents();
+    });
+  </script>
