+      <div class="journal-header">
+        <div>
+          <h2 id="journal-heading">Roaster's Journal: How We Source Our Beans</h2>
+          <p class="journal-meta">From high-altitude smallholder farms to our local roastery</p>
+        </div>
+        <button type="button" id="summarize-btn" class="btn summarize-btn">Summarize</button>
+      </div>
+
+      <p id="summarize-status" class="summarize-status" role="status" aria-live="polite" hidden></p>
+
+      <div id="journal-summary" class="journal-summary" aria-live="polite" hidden>
+        <h3>Key Takeaways</h3>
+        <ul id="summary-list" class="summary-list"></ul>
+      </div>
+
+      <article id="journal-article" class="journal-content">
+        <p>
+          Every exceptional cup at The Daily Grind begins long before a single bean reaches our roastery. Our sourcing philosophy is built on multi-year, direct-trade partnerships with smallholder farmers and cooperatives across the high-altitude coffee belts of Ethiopia's Yirgacheffe region, Colombia's Huila highlands, and Guatemala's volcanic Antigua valley. By bypassing commodity brokers and working face-to-face with growers at origin, we guarantee farm-gate prices at least 40% above Fair Trade minimums—ensuring that the families tending the trees can reinvest in soil health, shade canopy restoration, and local water conservation.
+        </p>
+        <p>
+          We specifically seek out micro-lots cultivated between 1,600 and 2,200 meters above sea level under native shade trees. At these cooler elevations, coffee cherries mature slowly over several months, concentrating complex organic acids and natural sugars within the seed. During harvest season, pickers make multiple passes through each hillside parcel to harvest only deep-red cherries at peak ripeness, registering between 21 and 24 degrees Brix on handheld refractometers before a batch is ever accepted at the mill.
+        </p>
+        <p>
+          Within hours of harvest, cherries are delivered to community washing stations where processing is tailored to each varietal's natural character. Our Ethiopian Heirloom lots undergo traditional 36-hour spring-water fermentation followed by slow drying on raised African beds, unlocking vibrant jasmine aromatics and bergamot acidity. Meanwhile, our Colombian Caturra and Castillo lots are often processed using honey and extended anaerobic methods, preserving lush stone-fruit sweetness and a velvety, syrupy body.
+        </p>
+        <p>
+          Before export, every parchment lot is rested in climate-controlled warehouses, milled, and evaluated by our quality team alongside local Q-Graders. Only lots scoring 86 points or higher on the Specialty Coffee Association scale—and measuring a stable 10.5% to 11.5% moisture content with zero primary defects—are sealed in hermetic GrainPro liners for ocean transit. Once the green coffee arrives at our local roastery, we craft small-batch roast profiles that honor the terroir and craftsmanship of the farmers who grew it.
+        </p>
+      </article>
+    </section>
   </main>

   <footer>
     <div class="footer-links">
@@ -206,7 +329,113 @@
     </div>
     <p>&copy; 2026 The Daily Grind Coffee Co. All rights reserved.</p>
   </footer>

+  <script>
+    (async () => {
+      const summarizeBtn = document.getElementById('summarize-btn');
+      const statusEl = document.getElementById('summarize-status');
+      const summaryContainer = document.getElementById('journal-summary');
+      const summaryList = document.getElementById('summary-list');
+      const articleEl = document.getElementById('journal-article');
+
+      const options = {
+        type: 'key-points',
+        format: 'plain-text',
+        length: 'medium',
+      };
+
+      function showStatus(message) {
+        statusEl.textContent = message;
+        statusEl.hidden = false;
+      }
+
+      function disableWithFallback(message) {
+        summarizeBtn.disabled = true;
+        showStatus(message);
+      }
+
+      if (!('Summarizer' in self)) {
+        disableWithFallback('Local summarization is currently unsupported in this browser.');
+        return;
+      }
+
+      let availability;
+      try {
+        availability = await Summarizer.availability(options);
+      } catch (err) {
+        disableWithFallback('Local summarization is currently unavailable in this browser.');
+        return;
+      }
+
+      if (availability === 'unavailable') {
+        disableWithFallback('Local summarization is currently unavailable on this device.');
+        return;
+      }
+
+      let summarizerInstance = null;
+
+      summarizeBtn.addEventListener('click', async () => {
+        summarizeBtn.disabled = true;
+
+        try {
+          const currentAvailability = await Summarizer.availability(options);
+          if (currentAvailability === 'unavailable') {
+            disableWithFallback('Local summarization is currently unavailable on this device.');
+            return;
+          }
+
+          if (!summarizerInstance) {
+            if (currentAvailability === 'downloadable' || currentAvailability === 'downloading') {
+              showStatus('Downloading on-device AI model (0%)...');
+            } else {
+              showStatus('Initializing on-device AI summarizer...');
+            }
+
+            summarizerInstance = await Summarizer.create({
+              ...options,
+              monitor(m) {
+                m.addEventListener('downloadprogress', (e) => {
+                  const percent = e.total
+                    ? Math.round((e.loaded / e.total) * 100)
+                    : Math.round(e.loaded * 100);
+                  console.log(`Downloaded ${percent}%`);
+                  showStatus(`Downloading on-device AI model (${percent}%)...`);
+                });
+              },
+            });
+          }
+
+          showStatus('Summarizing article...');
+
+          const longText = articleEl.innerText;
+          const summary = await summarizerInstance.summarize(longText, {
+            context: 'This article from a specialty coffee roaster explains their ethical direct-trade bean sourcing, harvesting, processing, and quality control process.',
+          });
+
+          const points = summary
+            .split(/\r?\n/)
+            .map((line) => line.replace(/^[\s*\-•\d.)]+/, '').trim())
+            .filter(Boolean);
+
+          summaryList.replaceChildren();
+          for (const point of points) {
+            const li = document.createElement('li');
+            li.textContent = point;
+            summaryList.appendChild(li);
+          }
+
+          summaryContainer.hidden = false;
+          statusEl.hidden = true;
+          summarizeBtn.textContent = 'Summarize Again';
+          summarizeBtn.disabled = false;
+        } catch (error) {
+          console.error('Summarization failed:', error);
+          showStatus('Unable to generate summary using the browser AI model.');
+          summarizeBtn.disabled = false;
+        }
+      });
+    })();
+  </script>
 </body>

 </html>

