+import http from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { createHash, randomBytes } from 'node:crypto';
+import dns from 'node:dns/promises';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { decodeSdJwtSync, SDJwtInstance } from '@sd-jwt/core';
+import { createRemoteJWKSet, importJWK, jwtVerify } from 'jose';
+
+const __dirname = path.dirname(fileURLToPath(import.meta.url));
+const PORT = Number(process.env.PORT || 11222);
+const RP_ORIGIN = process.env.RP_ORIGIN || `http://localhost:${PORT}`;
+const ORIGIN_TRIAL_TOKEN = process.env.ORIGIN_TRIAL_TOKEN || 'ORIGIN_TRIAL_TOKEN_PLACEHOLDER';
+
+// Server-side session store mapping session ID -> single-use cryptographic nonce
+// Never store the expected nonce value directly inside a client cookie.
+const sessionNonces = new Map();
+
+// IETF draft-hardt-email-verification-02 (§3.3, §5.1.1) specifies RFC 9864 'Ed25519' and 'ES256'.
+// Include 'EdDSA' while live issuers (e.g. Gmail) and Chrome Origin Trial builds finish
+// transitioning from 'EdDSA' (with crv: 'Ed25519') to 'Ed25519'.
+const ALLOWED_ALGS = ['Ed25519', 'EdDSA', 'ES256'];
+const normalizeAlg = (alg) => (alg === 'Ed25519' ? 'EdDSA' : alg);
+
+const hasher = (data, alg) =>
+  createHash(alg === 'sha-256' ? 'sha256' : alg).update(data).digest();
+
+/**
+ * Generates a fresh 256-bit (32-byte) cryptographic nonce per form render
+ * and stores it in server-side session state keyed by an HttpOnly, Secure, SameSite=Lax cookie.
+ */
+export function issueSessionNonce(sessionId = randomBytes(16).toString('base64url')) {
+  const nonce = randomBytes(32).toString('base64url');
+  sessionNonces.set(sessionId, nonce);
+  return { sessionId, nonce };
+}
+
+/**
+ * Atomically reads and deletes the single-use nonce from server-side session state
+ * so an intercepted token cannot be replayed.
+ */
+export function consumeSessionNonce(sessionId) {
+  if (!sessionId || !sessionNonces.has(sessionId)) {
+    return null;
+  }
+  const expectedNonce = sessionNonces.get(sessionId);
+  sessionNonces.delete(sessionId);
+  return expectedNonce;
+}
+
+/**
+ * Verifies an Email Verification Token (EVT + KB-JWT) presentation on the server.
+ */
+export async function verifyEmailVerificationToken({
+  rawToken,
+  submittedEmail,
+  expectedNonce,
+  expectedAudience = RP_ORIGIN,
+}) {
+  // Step 1: Parse the SD-JWT claims and validate the email address
+  const decoded = decodeSdJwtSync(rawToken, hasher);
+  const evtPayload = decoded.jwt?.payload;
+  const iss = evtPayload?.iss;
+
+  if (!expectedNonce || !decoded.kbJwt || !iss || evtPayload.email_verified !== true) {
+    throw new Error('Missing nonce, KB-JWT, issuer, or email_verified !== true.');
+  }
+
+  // MANDATORY: Compare email addresses case-insensitively while preserving the submitted email string
+  if (evtPayload.email?.toLowerCase() !== submittedEmail.toLowerCase()) {
+    throw new Error('Submitted email does not match the EVT email claim.');
+  }
+
+  // Step 2: Validate DNS TXT delegation and load the issuer JWKS
+  const domain = submittedEmail.split('@')[1];
+  if (!domain) {
+    throw new Error('Invalid email domain.');
+  }
+
+  const txtRecords = (await dns.resolveTxt(`_email-verification.${domain}`)).map((r) =>
+    r.join('')
+  );
+  if (
+    !txtRecords.some(
+      (txt) => txt.startsWith('iss=') && `https://${txt.slice(4).trim()}` === iss
+    )
+  ) {
+    throw new Error(`Issuer "${iss}" is not delegated via DNS for "${domain}".`);
+  }
+
+  const discoveryUrl = new URL('/.well-known/email-verification', iss);
+  if (discoveryUrl.protocol !== 'https:') {
+    throw new Error('Issuer must use HTTPS.');
+  }
+
+  const metadata = await (await fetch(discoveryUrl)).json();
+  if (metadata.issuer !== iss || !metadata.jwks_uri?.startsWith('https://')) {
+    throw new Error('Invalid issuer metadata or non-HTTPS jwks_uri.');
+  }
+
+  const issuerJwks = createRemoteJWKSet(new URL(metadata.jwks_uri));
+
+  // Step 3: Verify the EVT signature and Key Binding JWT (KB-JWT)
+  const evtOptions = {
+    typ: 'ev+sd-jwt',
+    issuer: iss,
+    algorithms: ALLOWED_ALGS,
+    maxTokenAge: '5m',
+    clockTolerance: '1m',
+  };
+
+  const sdJwt = new SDJwtInstance({
+    hasher,
+    verifier: async (data, sig) => {
+      const compactEvt = `${data}.${sig}`;
+      try {
+        await jwtVerify(compactEvt, issuerJwks, evtOptions);
+      } catch (err) {
+        // When `kid` is omitted (e.g. Gmail) and multiple keys match in the JWKS,
+        // jose throws ERR_JWKS_MULTIPLE_MATCHING_KEYS, which yields each matching CryptoKey.
+        if (err?.code !== 'ERR_JWKS_MULTIPLE_MATCHING_KEYS') throw err;
+        let matched = false;
+        for await (const publicKey of err) {
+          try {
+            await jwtVerify(compactEvt, publicKey, evtOptions);
+            matched = true;
+            break;
+          } catch {}
+        }
+        if (!matched) throw err;
+      }
+      return true;
+    },
+    kbVerifier: async (data, sig) => {
+      const holderJwk = evtPayload.cnf?.jwk;
+      const holderAlg = holderJwk?.alg;
+      const kbAlg = decoded.kbJwt.header.alg;
+      if (
+        !holderAlg ||
+        !kbAlg ||
+        !ALLOWED_ALGS.includes(holderAlg) ||
+        !ALLOWED_ALGS.includes(kbAlg) ||
+        normalizeAlg(kbAlg) !== normalizeAlg(holderAlg)
+      ) {
+        throw new Error('Missing, disallowed, or mismatched KB-JWT algorithm.');
+      }
+      const holderKey = await importJWK(holderJwk, kbAlg);
+      await jwtVerify(`${data}.${sig}`, holderKey, {
+        typ: 'kb+jwt',
+        audience: expectedAudience,
+        algorithms: [kbAlg],
+        maxTokenAge: '5m',
+        clockTolerance: '1m',
+      });
+      return true;
+    },
+  });
+
+  const verified = await sdJwt.verify(rawToken, {
+    requiredClaimKeys: ['email', 'email_verified'],
+    keyBindingNonce: expectedNonce,
+    expectedKeyBindingAudience: expectedAudience,
+    keyBindingMaxAgeSeconds: 300,
+    skewSeconds: 60,
+  });
+
+  return verified;
+}
+
+function parseCookies(cookieHeader = '') {
+  const cookies = {};
+  for (const part of cookieHeader.split(';')) {
+    const [key, ...rest] = part.trim().split('=');
+    if (key) {
+      cookies[key] = decodeURIComponent(rest.join('='));
+    }
+  }
+  return cookies;
+}
+
+function completeAccountCreation(submittedEmail, name) {
+  return {
+    verified: true,
+    method: 'email-verification-protocol',
+    email: submittedEmail,
+    name,
+    message: `Welcome to Daily Grind Rewards, ${name || submittedEmail}! Your email ownership was verified instantly without needing a passcode email.`,
+  };
+}
+
+function sendTraditionalVerificationEmail(submittedEmail, name) {
+  return {
+    verified: false,
+    method: 'fallback-email-otp',
+    email: submittedEmail,
+    name,
+    message: `Almost done! We sent a verification link to ${submittedEmail} to complete your Daily Grind Rewards registration.`,
+  };
+}
+
+/**
+ * Web-standard Request/Response handler for rewards sign-up and email verification.
+ */
+export async function handleSignupSubmission(request) {
+  const formData = await request.formData();
+  const submittedName = String(formData.get('name') || '').trim();
+  const submittedEmail = String(formData.get('email') || '').trim();
+  const rawToken = String(formData.get('token') || '').trim();
+
+  const cookies = parseCookies(request.headers.get('cookie') || '');
+  const expectedNonce = consumeSessionNonce(cookies.dg_evp_sid);
+
+  if (rawToken && expectedNonce) {
+    try {
+      await verifyEmailVerificationToken({
+        rawToken,
+        submittedEmail,
+        expectedNonce,
+        expectedAudience: RP_ORIGIN,
+      });
+      // Fast path: email ownership is cryptographically verified; skip OTP email.
+      return completeAccountCreation(submittedEmail, submittedName);
+    } catch (err) {
+      // Log token verification failures before falling back to standard email verification.
+      console.error('Email verification token check failed:', err);
+    }
+  }
+
+  // Fallback path: send standard OTP code or magic link email to submittedEmail.
+  return sendTraditionalVerificationEmail(submittedEmail, submittedName);
+}
+
+/**
+ * Node HTTP server serving the Daily Grind homepage with per-render nonces and verification endpoint.
+ */
+export function createAppServer() {
+  return http.createServer(async (req, res) => {
+    const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+
+    if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
+      const cookies = parseCookies(req.headers.cookie || '');
+      const { sessionId, nonce } = issueSessionNonce(cookies.dg_evp_sid);
+      const rawHtml = await readFile(path.join(__dirname, 'index.html'), 'utf8');
+      const renderedHtml = rawHtml
+        .replace('__SERVER_GENERATED_NONCE__', nonce)
+        .replace('ORIGIN_TRIAL_TOKEN_PLACEHOLDER', ORIGIN_TRIAL_TOKEN);
+
+      res.writeHead(200, {
+        'Content-Type': 'text/html; charset=utf-8',
+        'Cache-Control': 'no-store',
+        'Origin-Trial': ORIGIN_TRIAL_TOKEN,
+        'Set-Cookie': `dg_evp_sid=${encodeURIComponent(sessionId)}; Path=/; HttpOnly; Secure; SameSite=Lax`,
+      });
+      res.end(renderedHtml);
+      return;
+    }
+
+    if (
+      req.method === 'POST' &&
+      (url.pathname === '/api/rewards/signup' || url.pathname === '/api/verify-email')
+    ) {
+      const chunks = [];
+      for await (const chunk of req) {
+        chunks.push(chunk);
+      }
+      const rawBody = Buffer.concat(chunks).toString('utf8');
+      const params = new URLSearchParams(rawBody);
+      const submittedName = (params.get('name') || '').trim();
+      const submittedEmail = (params.get('email') || '').trim();
+      const rawToken = (params.get('token') || '').trim();
+
+      if (!submittedEmail) {
+        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(JSON.stringify({ error: 'Please provide a valid email address.' }));
+        return;
+      }
+
+      const cookies = parseCookies(req.headers.cookie || '');
+      const expectedNonce = consumeSessionNonce(cookies.dg_evp_sid);
+
+      let result;
+      if (rawToken && expectedNonce) {
+        try {
+          await verifyEmailVerificationToken({
+            rawToken,
+            submittedEmail,
+            expectedNonce,
+            expectedAudience: RP_ORIGIN,
+          });
+          result = completeAccountCreation(submittedEmail, submittedName);
+        } catch (err) {
+          console.error('Email verification token check failed:', err);
+          result = sendTraditionalVerificationEmail(submittedEmail, submittedName);
+        }
+      } else {
+        result = sendTraditionalVerificationEmail(submittedEmail, submittedName);
+      }
