+        background-color: #f1f5f9;
+        padding: 0.125rem 0.375rem;
+        border-radius: 0.25rem;
+      }
+
+      /* Independent theme container with specific numeric aspect-ratio override */
+      #independent-theme-container {
+        font-family: "Times New Roman", Times, serif;
+        font-size: 1.125rem;
+        font-size-adjust: 0.51;
+        text-wrap: pretty;
+        overflow-wrap: break-word;
+        background-color: #1e293b;
+        color: #f8fafc;
+        padding: 1.5rem;
+        border-radius: 0.5rem;
+        border: 1px solid #334155;
+      }
+
+      /* Fallback strategy for browsers without font-size-adjust support */
+      @supports not (font-size-adjust: from-font) {
+        #mixed-fonts-container {
+          line-height: 1.6;
+          font-size: 1.125rem;
+        }
+
+        #mixed-fonts-container code {
+          font-size: 0.95em;
+          line-height: 1.5;
+        }
