+    'notes',
+    'favorited',
+    'size',
+    'disabled',
+  ];
+
+  #internals;
+  #size = 'M';
+  #addedTimer = null;
+
+  constructor() {
+    super();
+    this.#internals = this.attachInternals();
+    this.attachShadow({ mode: 'open' });
