+    for (const note of notes) {
+      const li = document.createElement('li');
+      li.className = 'meta-tag';
+      li.textContent = note;
+      tagsEl.append(li);
+    }
+
+    this.#syncFavoriteState();
+    this.#updateSizeUI();
+  }
+}
